import React from 'react';

function List_trains({data}) {
  console.log(data)
  return (
    <div style={{backgroundColor: '#066467', height: '73vh', width: '97.6vw'}}>
      {data.map(train => (
        <Train key={train.id} value={train} />
      ))}
    </div>
  )
}

export default List_trains;
